      const loaded=await Promise.allSettled([['grassClumps','terrain/grass-clumps'],['nature','environment/alpine-nature']].map(async([key,file])=>{const gltf=await loader.loadAsync('/assets/karts/'+file+'.glb?v=alpine-assets-20261007-v3');assets[key]=gltf.scene;library.add(gltf.scene);}));
